// ---- Mars Life Line style header (generated by scripts/kiln-style-sync.mjs from src/style/tokens.json, style v2) ----
// Paste at the top of every .kiln.js source. Do not edit colours here; edit tokens.json and re-run npm run style:sync.
const PALETTE = {
  'space-deep': 0x20283D,
  'shadow-plum': 0x765768,
  'regolith-mid': 0xB95C40,
  'regolith-light': 0xE6A26A,
  'structure-white': 0xF2E5D2,
  'structure-gray': 0x686976,
  'trim-dark': 0x303240,
  'accent-orange': 0xFF8A24,
  'accent-cyan': 0x54E5F5,
  'accent-blue': 0x35CFFF,
  'glass-tint': 0xEBD9C5,
  'cell-blue': 0x2F58B8
};

const BUDGETS = {"small-prop":1500,"medium-prop":6000,"vehicle":9000,"building":12000,"character":8000,"rock":400};
const SEGMENTS = {"small":8,"default":12,"large":16};

// Bevel radius for roundedBoxGeo: ratio of the smallest dimension (style range 0.06-0.12).
function bevel(w, h, d, ratio = 0.09) {
  return Math.min(w, h, d) * ratio;
}

// One shared material per role. Variants (e.g. structure-gray) take an explicit colour token.
function styleMaterials() {
  const m = {"matte-environment":{"description":"Terrain, rocks, craters, mountains. Fully matte, no reflections.","colors":["regolith-mid","regolith-light","shadow-plum"],"roughness":0.95,"metalness":0},"smooth-structure":{"description":"Buildings, modules, vehicles, suits, crates. Clean satin finish, never mirror-like.","colors":["structure-white","structure-gray"],"roughness":0.55,"metalness":0.05},"accent-paint":{"description":"Non-glowing orange colour blocking: side panels, crate faces, dome base band, suit pads, wheel hubs.","colors":["accent-orange"],"roughness":0.6,"metalness":0},"dark-trim":{"description":"Tyres, recesses, joints, vents.","colors":["trim-dark"],"roughness":0.85,"metalness":0},"emissive-warm":{"description":"Door frames, window strips, headlights. Selected surfaces only.","colors":["accent-orange"],"emissive":"accent-orange","emissiveIntensity":1.6,"roughness":0.5,"metalness":0},"emissive-cool":{"description":"Beacons, indicators, screens. Smaller and rarer than warm lights.","colors":["accent-cyan","accent-blue"],"emissive":"accent-cyan","emissiveIntensity":1.4,"roughness":0.5,"metalness":0},"glass":{"description":"Greenhouse domes, module windows. Light tint, soft highlight, see-through.","colors":["glass-tint"],"roughness":0.15,"metalness":0,"opacity":0.35},"visor":{"description":"Helmet visors and vehicle windshields. Opaque near-black, glossy, shows a soft highlight.","colors":["space-deep"],"roughness":0.12,"metalness":0.1},"solar-cell":{"description":"Solar panel cell faces. Deep blue, semi-gloss, framed by structure-white grid bars.","colors":["cell-blue"],"roughness":0.35,"metalness":0.1}};
  const make = (role, colorToken) => {
    const spec = m[role];
    const color = PALETTE[colorToken ?? spec.colors[0]];
    const name = colorToken && colorToken !== spec.colors[0] ? role + ':' + colorToken : role;
    if (role === 'glass') return glassMaterial(color, { opacity: spec.opacity, roughness: spec.roughness, metalness: spec.metalness, name });
    const opts = { roughness: spec.roughness, metalness: spec.metalness, name };
    if (spec.emissive) Object.assign(opts, { emissive: PALETTE[spec.emissive], emissiveIntensity: spec.emissiveIntensity });
    return gameMaterial(color, opts);
  };
  return {
    rock: make('matte-environment'),
    rockLight: make('matte-environment', 'regolith-light'),
    rockShadow: make('matte-environment', 'shadow-plum'),
    panel: make('smooth-structure'),
    panelGray: make('smooth-structure', 'structure-gray'),
    accent: make('accent-paint'),
    trim: make('dark-trim'),
    glowWarm: make('emissive-warm'),
    glowCool: make('emissive-cool'),
    glowBlue: make('emissive-cool', 'accent-blue'),
    glass: make('glass'),
    visor: make('visor'),
    solarCell: make('solar-cell'),
  };
}
// ---- end style header ----

const meta = {
  name: 'astronaut-suit-rack',
  role: 'prop',
  reference: 'models and assets images/phase-4/astronaut-suit-rack.png'
};

function build() {
  const root = createRoot('astronaut-suit-rack');
  const m = styleMaterials();
  m.panel.flatShading = false;
  m.visor.flatShading = false;

  // -------------------------------------------------------------------------
  // 1. RACK FRAME & BASE STAND
  // -------------------------------------------------------------------------
  // Base plinth slab with front chamfer
  createPart('BasePlinth', boxGeo(0.56, 0.08, 0.82), m.panelGray, {
    position: [0.08, 0.04, 0],
    parent: root
  });
  createPart('BaseStep', boxGeo(0.50, 0.04, 0.74), m.panelGray, {
    position: [0.08, 0.08, 0],
    parent: root
  });

  // Upright side posts extending up to frame helmet (Y = 1.90m)
  createPart('PostLeft', boxGeo(0.18, 1.84, 0.09), m.panelGray, {
    position: [-0.09, 1.00, -0.365],
    parent: root
  });
  createPart('PostRight', boxGeo(0.18, 1.84, 0.09), m.panelGray, {
    position: [-0.09, 1.00, 0.365],
    parent: root
  });
  createPart('TopCrossbar', boxGeo(0.18, 0.09, 0.66), m.panelGray, {
    position: [-0.09, 1.88, 0],
    parent: root
  });

  // Recessed ivory backplate
  createPart('BackPlate', boxGeo(0.04, 1.76, 0.65), m.panel, {
    position: [-0.10, 0.98, 0],
    parent: root
  });

  // Upper shelf
  createPart('ShelfSlab', boxGeo(0.44, 0.06, 0.74), m.panelGray, {
    position: [0.08, 1.40, 0],
    parent: root
  });
  createPart('BracketLeft', boxGeo(0.28, 0.16, 0.06), m.panelGray, {
    position: [0.02, 1.30, -0.33],
    parent: root
  });
  createPart('BracketRight', boxGeo(0.28, 0.16, 0.06), m.panelGray, {
    position: [0.02, 1.30, 0.33],
    parent: root
  });

  // Hanging rail under shelf
  createPart('HangingRail', cylinderGeo(0.02, 0.02, 0.62, 10), m.panelGray, {
    position: [0.08, 1.28, 0],
    rotation: [90, 0, 0],
    parent: root
  });
  // Thick hook connecting rail down to collar
  createPart('HangerHook', cylinderGeo(0.016, 0.016, 0.14, 8), m.panelGray, {
    position: [0.08, 1.20, 0],
    parent: root
  });

  // -------------------------------------------------------------------------
  // 2. HELMET (RESTING ON SHELF)
  // -------------------------------------------------------------------------
  const helmet = createPivot('Helmet', [0.10, 1.43, 0], root);

  // Cradle ring
  createPart('HelmetCradle', cylinderGeo(0.15, 0.16, 0.035, 12), m.panelGray, {
    position: [0, 0.02, 0],
    parent: helmet
  });
  // Helmet shell
  createPart('HelmetShell', sphereGeo(0.175, 12, 10), m.panel, {
    position: [0, 0.20, 0],
    parent: helmet
  });
  // Visor (glossy forward sphere)
  createPart('HelmetVisor', sphereGeo(0.150, 12, 10), m.visor, {
    position: [0.06, 0.20, 0],
    parent: helmet
  });
  // Helmet Brow Visor Trim
  createPart('HelmetBrow', boxGeo(0.05, 0.038, 0.25), m.panel, {
    position: [0.08, 0.31, 0],
    parent: helmet
  });

  // Ear Pods (left & right)
  for (const s of [-1, 1]) {
    const side = s > 0 ? 'R' : 'L';
    createPart('EarPodBase_' + side, cylinderGeo(0.048, 0.048, 0.022, 10), m.panelGray, {
      position: [0, 0.20, s * 0.175],
      rotation: [90, 0, 0],
      parent: helmet
    });
    createPart('EarCap_' + side, cylinderGeo(0.040, 0.040, 0.014, 10), m.accent, {
      position: [0, 0.20, s * 0.188],
      rotation: [90, 0, 0],
      parent: helmet
    });
  }

  // -------------------------------------------------------------------------
  // 3. ASTRONAUT SUIT (HEADLESS ON HANGER)
  // -------------------------------------------------------------------------
  const suit = createPivot('Suit', [0.08, 0, 0], root);

  // Large neck ring collar & dark cavity
  createPart('SuitNeckRing', cylinderGeo(0.14, 0.15, 0.06, 12), m.panel, {
    position: [0, 1.13, 0],
    parent: suit
  });
  createPart('SuitNeckCavity', cylinderGeo(0.11, 0.11, 0.065, 12), m.trim, {
    position: [0, 1.132, 0],
    parent: suit
  });

  // Bulky rounded torso
  createPart('SuitTorso', boxGeo(0.26, 0.34, 0.40), m.panel, {
    position: [0, 0.96, 0],
    parent: suit
  });
  // Harness straps
  createPart('StrapLeft', boxGeo(0.27, 0.32, 0.045), m.panelGray, {
    position: [0, 0.97, -0.13],
    parent: suit
  });
  createPart('StrapRight', boxGeo(0.27, 0.32, 0.045), m.panelGray, {
    position: [0, 0.97, 0.13],
    parent: suit
  });

  // Front chest control pack
  createPart('ChestPack', boxGeo(0.05, 0.20, 0.20), m.panel, {
    position: [0.14, 0.98, 0],
    parent: suit
  });
  // Upper slate buttons
  createPart('BtnTopL', boxGeo(0.025, 0.055, 0.055), m.panelGray, {
    position: [0.17, 1.035, -0.05],
    parent: suit
  });
  createPart('BtnTopR', boxGeo(0.025, 0.055, 0.055), m.panelGray, {
    position: [0.17, 1.035, 0.05],
    parent: suit
  });
  // Lower orange buttons
  createPart('BtnBotL', boxGeo(0.025, 0.045, 0.045), m.accent, {
    position: [0.17, 0.935, -0.05],
    parent: suit
  });
  createPart('BtnBotR', boxGeo(0.025, 0.045, 0.045), m.accent, {
    position: [0.17, 0.935, 0.05],
    parent: suit
  });
  createPart('ChestSlot', boxGeo(0.015, 0.012, 0.04), m.panelGray, {
    position: [0.17, 0.935, 0],
    parent: suit
  });

  // Thick orange waist belt & buckle
  createPart('WaistBelt', boxGeo(0.27, 0.07, 0.41), m.accent, {
    position: [0, 0.79, 0],
    parent: suit
  });
  createPart('BeltBuckle', boxGeo(0.035, 0.07, 0.07), m.panelGray, {
    position: [0.14, 0.79, 0],
    parent: suit
  });

  // Pelvis / crotch
  createPart('Pelvis', boxGeo(0.25, 0.14, 0.36), m.panel, {
    position: [0, 0.69, 0],
    parent: suit
  });

  // Puffy Arms (Left & Right)
  for (const s of [-1, 1]) {
    const side = s > 0 ? 'R' : 'L';
    // Shoulder cap
    createPart('Shoulder_' + side, boxGeo(0.14, 0.09, 0.10), m.accent, {
      position: [0, 1.06, s * 0.25],
      parent: suit
    });
    // Upper arm
    createPart('UpperArm_' + side, cylinderGeo(0.065, 0.06, 0.22, 10), m.panel, {
      position: [0, 0.93, s * 0.27],
      rotation: [0, 0, s * -5],
      parent: suit
    });
    // Arm orange stripe
    createPart('ArmBand_' + side, cylinderGeo(0.068, 0.068, 0.04, 10), m.accent, {
      position: [0, 0.88, s * 0.275],
      parent: suit
    });
    // Dark elbow ring
    createPart('ElbowBand_' + side, cylinderGeo(0.062, 0.062, 0.035, 10), m.panelGray, {
      position: [0, 0.82, s * 0.28],
      parent: suit
    });
    // Forearm
    createPart('Forearm_' + side, cylinderGeo(0.06, 0.055, 0.20, 10), m.panel, {
      position: [0, 0.70, s * 0.29],
      parent: suit
    });
    // Thick glove hand
    createPart('Glove_' + side, boxGeo(0.11, 0.16, 0.10), m.panelGray, {
      position: [0.02, 0.55, s * 0.30],
      parent: suit
    });
  }

  // Bulky Legs & Boots (Left & Right)
  for (const s of [-1, 1]) {
    const side = s > 0 ? 'R' : 'L';
    // Thigh
    createPart('Thigh_' + side, cylinderGeo(0.09, 0.082, 0.24, 10), m.panel, {
      position: [0, 0.53, s * 0.125],
      parent: suit
    });
    // Orange knee band & chunky front pad
    createPart('KneeBand_' + side, cylinderGeo(0.088, 0.088, 0.07, 10), m.accent, {
      position: [0, 0.39, s * 0.125],
      parent: suit
    });
    createPart('KneePad_' + side, boxGeo(0.05, 0.10, 0.11), m.accent, {
      position: [0.06, 0.39, s * 0.125],
      parent: suit
    });
    // Shin
    createPart('Shin_' + side, cylinderGeo(0.082, 0.088, 0.22, 10), m.panel, {
      position: [0, 0.25, s * 0.125],
      parent: suit
    });
    // Slate boot cuff
    createPart('BootCuff_' + side, cylinderGeo(0.095, 0.095, 0.05, 10), m.panelGray, {
      position: [0, 0.14, s * 0.125],
      parent: suit
    });
    // Rounded boot foot resting on step
    createPart('Boot_' + side, boxGeo(0.26, 0.12, 0.15), m.panelGray, {
      position: [0.04, 0.10, s * 0.125],
      parent: suit
    });
  }

  defineBudget({ triangles: BUDGETS['medium-prop'] }, root);
  return root;
}
